--
-- Table structure for table `tblresponse`
--

DROP TABLE IF EXISTS `tblresponse`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tblresponse` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `question_id` int NOT NULL,
  `subject_id` int NOT NULL,
  `topic_id` int NOT NULL,
  `student_answer` text NOT NULL,
  `student_graphic` longtext,
  `response_timestamp` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `time_taken` int DEFAULT NULL,
  `ai_feedback` text,
  `ai_processed` tinyint(1) DEFAULT '0',
  `ai_timestamp` timestamp NULL DEFAULT NULL,
  `ai_error` text,
  `estimated_grade` varchar(10) DEFAULT NULL,
  `completion_status` enum('started','submitted','assessed') DEFAULT 'started',
  `session_id` varchar(100) DEFAULT NULL,
  `attempt_number` int DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `teacher_comment` text,
  `teacher_rating` enum('R','A','G') DEFAULT NULL COMMENT 'R=Red, A=Amber, G=Green',
  `teacher_feedback_timestamp` timestamp NULL DEFAULT NULL,
  `teacher_id` int DEFAULT NULL COMMENT 'ID of teacher who provided feedback',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `unique_user_question_attempt` (`user_id`,`question_id`,`attempt_number`) USING BTREE,
  KEY `idx_user_responses` (`user_id`,`response_timestamp`) USING BTREE,
  KEY `idx_question_responses` (`question_id`) USING BTREE,
  KEY `idx_subject_topic` (`subject_id`,`topic_id`) USING BTREE,
  KEY `idx_session` (`session_id`) USING BTREE,
  KEY `idx_completion_status` (`completion_status`) USING BTREE,
  KEY `fk_response_topic` (`topic_id`,`subject_id`) USING BTREE,
  CONSTRAINT `fk_response_question` FOREIGN KEY (`question_id`) REFERENCES `tblquestion` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_response_subject` FOREIGN KEY (`subject_id`) REFERENCES `tblsubject` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_response_topic` FOREIGN KEY (`topic_id`, `subject_id`) REFERENCES `tbltopic` (`id`, `subjectid`) ON DELETE CASCADE,
  CONSTRAINT `fk_response_user` FOREIGN KEY (`user_id`) REFERENCES `tbluser` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2119 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

