--
-- Table structure for table `tbluser_stats`
--

DROP TABLE IF EXISTS `tbluser_stats`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbluser_stats` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `subject_id` int NOT NULL,
  `topic_id` int DEFAULT NULL,
  `total_questions_attempted` int DEFAULT '0',
  `total_questions_completed` int DEFAULT '0',
  `average_grade` decimal(3,2) DEFAULT NULL,
  `total_time_spent` int DEFAULT '0',
  `last_activity` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `unique_user_subject_topic` (`user_id`,`subject_id`,`topic_id`) USING BTREE,
  KEY `fk_stats_subject` (`subject_id`) USING BTREE,
  KEY `fk_stats_topic` (`topic_id`,`subject_id`) USING BTREE,
  CONSTRAINT `fk_stats_subject` FOREIGN KEY (`subject_id`) REFERENCES `tblsubject` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_stats_topic` FOREIGN KEY (`topic_id`, `subject_id`) REFERENCES `tbltopic` (`id`, `subjectid`) ON DELETE CASCADE,
  CONSTRAINT `fk_stats_user` FOREIGN KEY (`user_id`) REFERENCES `tbluser` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4236 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

